  { check: (p) => p.name !== '', message: '名字不能是空字串' },
];

const rules = [
  { check: (p) => p.age > 0, message: '年齡必須是正數' },
  { check: (p) => p.name !== '', message: '名字不能是空字串' },
];

function validate(person, rules) {
  return rules.filter((rule) => !rule.check(person)).map((rule) => rule.message);
}

console.log(validate({ age: -5, name: '' }, rules));
console.log(validate({ age: 20, name: '小明' }, rules));

